-- A duplicate membership's part assignments move to the kept membership first: the active one,
-- then an admin one, then the earliest.
UPDATE `MemberPart` SET `membershipId` = (SELECT `keep`.`id` FROM `EnsembleMember` `dup` JOIN `EnsembleMember` `keep` ON `keep`.`ensembleId` = `dup`.`ensembleId` AND `keep`.`userId` = `dup`.`userId` WHERE `dup`.`id` = `MemberPart`.`membershipId` ORDER BY (`keep`.`status` = 'active') DESC, (`keep`.`role` = 'admin') DESC, julianday(`keep`.`joinedAt`), `keep`.rowid LIMIT 1);--> statement-breakpoint
DELETE FROM `EnsembleMember` WHERE rowid IN (SELECT `rid` FROM (SELECT rowid AS `rid`, ROW_NUMBER() OVER (PARTITION BY `ensembleId`, `userId` ORDER BY (`status` = 'active') DESC, (`role` = 'admin') DESC, julianday(`joinedAt`), rowid) AS `rn` FROM `EnsembleMember`) WHERE `rn` > 1);--> statement-breakpoint
DELETE FROM `MemberPart` WHERE rowid IN (SELECT `rid` FROM (SELECT rowid AS `rid`, ROW_NUMBER() OVER (PARTITION BY `membershipId`, `partId` ORDER BY rowid) AS `rn` FROM `MemberPart`) WHERE `rn` > 1);--> statement-breakpoint
-- Attendance: the first check-in.
DELETE FROM `Attendance` WHERE rowid IN (SELECT `rid` FROM (SELECT rowid AS `rid`, ROW_NUMBER() OVER (PARTITION BY `eventId`, `userId` ORDER BY julianday(`checkedInAt`), rowid) AS `rn` FROM `Attendance`) WHERE `rn` > 1);--> statement-breakpoint
-- RSVP: the latest answer.
DELETE FROM `EventRsvp` WHERE rowid IN (SELECT `rid` FROM (SELECT rowid AS `rid`, ROW_NUMBER() OVER (PARTITION BY `eventId`, `userId` ORDER BY julianday(`respondedAt`) DESC, rowid DESC) AS `rn` FROM `EventRsvp`) WHERE `rn` > 1);--> statement-breakpoint
DELETE FROM `TaskCompletion` WHERE rowid IN (SELECT `rid` FROM (SELECT rowid AS `rid`, ROW_NUMBER() OVER (PARTITION BY `taskId`, `userId` ORDER BY julianday(`completedAt`), rowid) AS `rn` FROM `TaskCompletion`) WHERE `rn` > 1);--> statement-breakpoint
DELETE FROM `SeasonMembership` WHERE rowid IN (SELECT `rid` FROM (SELECT rowid AS `rid`, ROW_NUMBER() OVER (PARTITION BY `seasonId`, `userId` ORDER BY julianday(`joinedAt`), rowid) AS `rn` FROM `SeasonMembership`) WHERE `rn` > 1);--> statement-breakpoint
-- Group membership: one with a role, then the earliest.
DELETE FROM `GroupMembership` WHERE rowid IN (SELECT `rid` FROM (SELECT rowid AS `rid`, ROW_NUMBER() OVER (PARTITION BY `groupId`, `userId` ORDER BY (`role` IS NULL), julianday(`addedAt`), rowid) AS `rn` FROM `GroupMembership`) WHERE `rn` > 1);--> statement-breakpoint
DELETE FROM `SongPart` WHERE rowid IN (SELECT `rid` FROM (SELECT rowid AS `rid`, ROW_NUMBER() OVER (PARTITION BY `songId`, `partId` ORDER BY rowid) AS `rn` FROM `SongPart`) WHERE `rn` > 1);--> statement-breakpoint
DELETE FROM `SeasonSong` WHERE rowid IN (SELECT `rid` FROM (SELECT rowid AS `rid`, ROW_NUMBER() OVER (PARTITION BY `seasonId`, `songId` ORDER BY julianday(`addedAt`), rowid) AS `rn` FROM `SeasonSong`) WHERE `rn` > 1);--> statement-breakpoint
